package com.primehr.performancemanagement.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity@Table(name="spms_intervention_rule",uniqueConstraints=@UniqueConstraint(name="uk_spms_intervention_exact_band",columnNames={"agency_id","policy_version_id","rating_scale_version_id","rating_band_id"}))
public class PerformanceInterventionRule extends RspAuditedEntity{public enum Action{NONE,ALERT,PIP_RECOMMENDED,PIP_REQUIRED}@Column(name="policy_version_id",nullable=false,length=36)private String policyVersionId;@Column(name="rating_scale_version_id",nullable=false,length=36)private String ratingScaleVersionId;@Column(name="rating_band_id",nullable=false,length=36)private String ratingBandId;@Enumerated(EnumType.STRING)@Column(name="intervention_action",nullable=false,length=30)private Action action;@Column(name="employee_message",length=2000)private String employeeMessage;@Column(name="created_by_rule",nullable=false,length=100)private String createdByRule;@Column(name="created_at_rule",nullable=false)private Instant createdAtRule;protected PerformanceInterventionRule(){}public PerformanceInterventionRule(String a,String policy,String scale,String band,Action action,String message,String actor,Instant at){super(a);policyVersionId=requiredText(policy,"policyVersionId");ratingScaleVersionId=requiredText(scale,"ratingScaleVersionId");ratingBandId=requiredText(band,"ratingBandId");this.action=action;employeeMessage=optionalText(message);createdByRule=requiredText(actor,"actor");createdAtRule=at;}public String getPolicyVersionId(){return policyVersionId;}public String getRatingScaleVersionId(){return ratingScaleVersionId;}public String getRatingBandId(){return ratingBandId;}public Action getAction(){return action;}public String getEmployeeMessage(){return employeeMessage;}public String getCreatedByRule(){return createdByRule;}public Instant getCreatedAtRule(){return createdAtRule;}}
